# Zero-Downtime Database Schema Migration Strategy

For multi-tenant SaaS deployments, here's a comprehensive approach to handling database schema migrations without downtime:

## Core Principles

1. **Backward Compatibility First** - Always design migrations that work with both old and new schemas simultaneously
2. **Feature Flags** - Use application-level flags to control when new code reads/writes the new schema
3. **Read-Write Splitting** - Route traffic during migration windows strategically
4. **Automated Validation** - Verify data integrity before, during, and after migrations

## Migration Strategy Options

### Option 1: Forward-Compatible Migrations (Recommended)

```python
# Example: Adding a column with default value
def add_column_with_default():
    """Add column that's compatible with both old and new code"""
    migration_sql = """
    ALTER TABLE users 
    ADD COLUMN new_feature_enabled BOOLEAN DEFAULT FALSE;

    -- Add index for performance
    CREATE INDEX idx_users_new_feature ON users(new_feature_enabled);
    """
    execute_migration(migration_sql)

# Application code handles both old and new schemas
def get_user_preferences(user_id):
    # Check if column exists before accessing
    if hasattr(db, 'column_exists('new_feature_enabled')'):
        return db.query("SELECT new_feature_enabled FROM users WHERE id = ?", user_id)
    else:
        return None  # Old schema path
```

### Option 2: Dual-Write Pattern for Critical Changes

```python
# Write to both schemas during transition period
def create_user(user_data):
    # Write to old schema (primary)
    db.execute("""
        INSERT INTO users_old (name, email, created_at) 
        VALUES (?, ?, ?)
    """, user_data['name'], user_data['email'], datetime.now())

    # Write to new schema (secondary during migration)
    if config.enable_new_schema:
        db.execute("""
            INSERT INTO users_new (name, email, created_at, metadata) 
            VALUES (?, ?, ?, ?)
        """, user_data['name'], user_data['email'], datetime.now(), json.dumps({}))

    return user_id

# Read from appropriate schema based on feature flag
def get_user(user_id):
    if config.enable_new_schema:
        return db.query("SELECT * FROM users_new WHERE id = ?", user_id)
    else:
        return db.query("SELECT * FROM users_old WHERE id = ?", user_id)
```

### Option 3: Blue-Green Database Migrations

```python
# Terraform example for database migration with read replicas
resource "aws_db_instance" "primary" {
  # Primary database (old schema)
}

resource "aws_db_instance" "replica" {
  # Replica for new schema testing
  db_instance_class = "db.t3.micro"

  # Enable cross-region replication for failover
  multi_az = true
}

# Migration script with validation
def migrate_with_validation():
    """Execute migration with multiple checkpoints"""

    migrations = [
        {
            'name': 'add_column',
            'sql': 'ALTER TABLE users ADD COLUMN new_field VARCHAR(255)',
            'validation': lambda: check_column_exists('new_field'),
            'rollback': 'ALTER TABLE users DROP COLUMN new_field'
        },
        {
            'name': 'create_index',
            'sql': 'CREATE INDEX idx_users_email ON users(email)',
            'validation': lambda: check_index_exists('idx_users_email'),
            'rollback': 'DROP INDEX idx_users_email'
        }
    ]

    for migration in migrations:
        try:
            execute(migration['sql'])
            if not migration['validation']():
                rollback(migration['rollback'])
                raise MigrationError(f"Validation failed for {migration['name']}")
            log_migration_success(migration['name'])
        except Exception as e:
            rollback(migration['rollback'])

